import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry with correct aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load texture from assets
  const imageUrl = config.assetsPaths?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const mapTexture = ctx.textureLoader.load(imageUrl);
  mapTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL texture node
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = textureNode(mapTexture);

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene transform
  const position = config.scenePosition || [1.25, 1.6, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  group.position.set(position[0], position[1], position[2]);
  group.rotation.order = 'XYZ';
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Store initial Y for animation reference
  const baseY = mesh.position.y;

  // Define interaction handlers
  group.userData.handlers = {
    onPointerEnter: () => {
      // Rise-in preset: y +0.15, power3.out, 0.7s
      gsap.to(mesh.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerLeave: () => {
      // Return to base position
      gsap.to(mesh.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
    onClick: () => {
      // Emit hub-pricing.select event
      if (ctx.emit) {
        ctx.emit('hub-pricing.select', { nodeId: config.id });
      }
    },
  };

  // Apply cinematic primitives from config
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(({ name, params }) => {
      if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
        ctx.primitives[name](group, params || {});
      }
    });
  }

  // Define cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP animations on this mesh
    gsap.killTweensOf(mesh.position);

    // Dispose of Three.js resources
    geometry.dispose();
    material.dispose();
    mapTexture.dispose();
  };

  return group;
}
